<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Controllers\Api\V1\Concerns\ApiResponse; use App\Http\Requests\Api\V1\Game\{StartGameSessionRequest,SubmitAnswerRequest,FinishGameSessionRequest}; use App\Http\Resources\Api\V1\GameSessionResource; use App\Models\{Answer,GameSession,Level,Question}; use App\Services\Game\{GameSessionService,AnswerQuestionService,FinishGameSessionService}; use Illuminate\Http\Request; use Throwable;
class GameSessionController extends Controller { use ApiResponse; public function start(StartGameSessionRequest $r, Level $level, GameSessionService $svc){ try{$s=$svc->start($r->user(),$level,$r->input('mode', 'level')); $q=$svc->getQuestionsForSession($s); $s->setRelation('questions',$q); return $this->success('Session démarrée.', new GameSessionResource($s),201);}catch(Throwable $e){return $this->businessError($e,'start game failed');}} public function show(Request $r, GameSession $session, GameSessionService $svc){ try{$svc->assertSessionOwner($r->user(),$session); return $this->success('Session.', new GameSessionResource($session->load('gameSessionAnswers')));}catch(Throwable $e){return $this->businessError($e,'show session failed');}} public function answer(SubmitAnswerRequest $r, GameSession $session, GameSessionService $own, AnswerQuestionService $svc){ try{$own->assertSessionOwner($r->user(),$session); $q=Question::findOrFail($r->validated('question_id')); $a=$r->validated('answer_id')?Answer::findOrFail($r->validated('answer_id')):null; $row=$svc->submitAnswerForUser($r->user(),$session,$q,$a,(int)$r->validated('response_time')); return $this->success('Réponse enregistrée.',['is_correct'=>$row->is_correct,'points_earned'=>$row->points_earned,'xp_earned'=>$row->xp_earned,'correct_answer_id'=>$q->answers()->where('is_correct',true)->value('id'),'explanation'=>$q->explanation,'session_score'=>$session->refresh()->score]);}catch(Throwable $e){return $this->businessError($e,'answer failed');}} public function finish(FinishGameSessionRequest $r, GameSession $session, GameSessionService $own, FinishGameSessionService $svc){ try{$own->assertSessionOwner($r->user(),$session); $s=$svc->finish($session); return $this->success('Session terminée.',['score'=>$s->score,'accuracy'=>$s->accuracy,'correct_answers'=>$s->correct_answers,'wrong_answers'=>$s->wrong_answers,'xp_earned'=>$s->xp_earned,'coins_earned'=>$s->coins_earned,'gems_earned'=>$s->gems_earned,'status'=>$s->status,'rewards'=>['xp'=>$s->xp_earned,'coins'=>$s->coins_earned,'gems'=>$s->gems_earned]]);}catch(Throwable $e){return $this->businessError($e,'finish failed');}} public function history(Request $r){ $q=$r->user()->gameSessions()->latest(); if($r->filled('status')){$q->where('status',$r->query('status'));} if($r->filled('mode')){$q->where('mode',$r->query('mode'));} $per=min(max((int)$r->query('per_page',15),1),50); return $this->success('Historique des parties.', GameSessionResource::collection($q->paginate($per)));} public function abandon(Request $r, GameSession $session, GameSessionService $svc){ try{$svc->assertSessionOwner($r->user(),$session); return $this->success('Session abandonnée.', new GameSessionResource($svc->abandon($session)));}catch(Throwable $e){return $this->businessError($e,'abandon failed');}}}
